// Generates src/generated/ (a @solana/kit client) from the Anchor IDL with Codama. Never edit src/generated by hand.
//
//   anchor build                                                      # writes target/idl/samite_escrow.json
//   pnpm --filter @samite/program-client generate --from-target       # copy that IDL into idl/, then generate
//   pnpm --filter @samite/program-client generate                     # regenerate from the committed idl/
//
// idl/samite_escrow.json is committed (target/ is not), so the client can be regenerated without a Rust toolchain,
// and CI checks that it matches what `anchor build` produces.
import { copyFileSync, readFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { rootNodeFromAnchor } from "@codama/nodes-from-anchor"
import { renderVisitor } from "@codama/renderers-js"
import { createFromRoot } from "codama"

const packageDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const idlPath = path.join(packageDir, "idl", "samite_escrow.json")

if (process.argv.includes("--from-target")) {
  copyFileSync(path.join(packageDir, "..", "..", "target", "idl", "samite_escrow.json"), idlPath)
  console.log("copied target/idl/samite_escrow.json → idl/samite_escrow.json")
}

const idl = JSON.parse(readFileSync(idlPath, "utf8"))
const codama = createFromRoot(rootNodeFromAnchor(idl))

await codama.accept(
  renderVisitor(packageDir, {
    // Import everything from @solana/kit (and its subpaths), our only runtime dependency.
    kitImportStrategy: "rootOnly",
    // Dependencies are pinned by hand in package.json.
    syncPackageJson: false,
    prettierOptions: { printWidth: 120, semi: false, singleQuote: false, trailingComma: "all" },
  }),
)
console.log(`generated src/generated/ from ${path.relative(packageDir, idlPath)}`)
